fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    // Ensure all input vectors have the same length
    let n = s1.len();
    assert_eq!(s2.len(), n, "Second vector has a different length");
    assert_eq!(s3.len(), n, "Third vector has a different length");

    // Pre-allocate the result vector with the required capacity
    let mut res = Vec::with_capacity(3 * n);

    // Interleave elements from the three input vectors
    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}

fn main() {
    let a = vec![1, 4, 7];
    let b = vec![2, 5, 8];
    let c = vec![3, 6, 9];
    let result = interleave(&a, &b, &c);
    println!("{:?}", result);
    // Output: [1, 2, 3, 4, 5, 6, 7, 8, 9]
}